import {api,setToken,hasToken,downloadReport} from './api.js';
import {icon} from './icons.js';
import {lineChart,barChart,donut} from './charts.js';

const root=document.querySelector('#app');
const toastTarget=document.querySelector('#toast');
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(n||0))+' ₽';
const integer=n=>new Intl.NumberFormat('ru-RU').format(Number(n||0));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shortDate=s=>{try{return new Date(s).toLocaleDateString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}catch{return '—'}};
const reasonLabels={size:'Не нашёл нужный размер',price:'Высокая цена',assortment:'Не подошёл ассортимент',service:'Не дождался помощи',just_looking:'Просто смотрел',other:'Другое'};
const statusLabels={open:'Открыт',located:'Найден',notified:'Уведомлён',converted:'Купил',closed:'Закрыт'};
const menu=[{id:'overview',label:'Главная',ico:'home'},{id:'traffic',label:'Посетители',ico:'users'},{id:'zones',label:'Карта магазина',ico:'grid'},{id:'demand',label:'Спрос и размеры',ico:'shirt'},{id:'stock',label:'Склады и остатки',ico:'layers'},{id:'feedback',label:'Опросы и отзывы',ico:'clipboard'},{id:'actions',label:'Рекомендации',ico:'sparkle'},{id:'monitor',label:'Контроль данных',ico:'activity'},{id:'integrations',label:'Интеграции',ico:'plug'},{id:'settings',label:'Настройки',ico:'settings'},{id:'team',label:'Сотрудники и доступ',ico:'shield'}];
const requestId=()=>crypto.randomUUID?.() || `browser-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const freshKiosk=()=>({rating:0,purchased:null,reason:'',liked:'',suggestion:'',liked_tags:[],improve_tags:[],request_id:requestId()});
const likedOptions={assortment:'Ассортимент',quality:'Качество вещей',service:'Обслуживание',atmosphere:'Атмосфера',fitting:'Примерочная'};
const improveOptions={size:'Наличие размеров',assortment:'Больше моделей',price:'Цены',service:'Помощь сотрудников',fitting:'Примерочные',queue:'Скорость обслуживания'};
const state={config:null,user:null,quality:null,posSources:[],kioskToken:null,kioskLink:null,devices:[],team:[],imports:[],pendingImport:null,stores:[],store:null,data:null,stock:[],experiments:[],slug:'central',days:30,page:'overview',menuOpen:false,kioskStep:0,kiosk:freshKiosk(),kioskReward:null,error:'',loading:false};
let toastTimeout;
function toast(message,isError=false){clearTimeout(toastTimeout);toastTarget.innerHTML=`<div class="toast-content ${isError?'toast-error':''}">${esc(message)}</div>`;toastTimeout=setTimeout(()=>toastTarget.innerHTML='',4400)}
const featureTag=()=>state.config?.demo?'<span class="tag demo">● ДЕМО · пример данных</span>':'<span class="tag">● Рабочие данные</span>';
function navHtml(){return menu.map(m=>`<button class="nav-btn ${state.page===m.id?'active':''}" data-nav="${m.id}" ${state.page===m.id?'aria-current="page"':''}>${icon(m.ico)}<span>${m.label}</span></button>`).join('')}
function cardStat(label,value,ico,delta,meta='',emphasis=false){const positive=delta==null?'neutral':delta<0?'down':'';const deltaText=delta==null?'Нет сравнения':`${delta>0?'+':''}${String(delta).replace('.',',')}${label==='Конверсия'?' п.п.':'%'}`;return `<div class="panel kpi"><div class="kpi-icon"><span>${esc(label)}</span>${icon(ico)}</div><div class="kpi-value monospace ${emphasis?'emphasis':''}">${esc(value)}</div><div class="kpi-meta"><span class="delta ${positive}">${esc(deltaText)}</span><span class="muted">${esc(meta)}</span></div></div>`}
function pane(title,content,opts=''){return `<section class="panel ${opts}"><div class="panel-body"><div class="panel-head"><h2 class="panel-title">${esc(title)}</h2></div>${content}</div></section>`}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="heading-right">${actions}</div></div>`}
function miniEmpty(ico,title,description){return `<div class="empty">${icon(ico,36)}<strong>${esc(title)}</strong><p>${esc(description)}</p></div>`}
function deltaText(value){return value===null||value===undefined?'Недостаточно данных':`${value>0?'+':''}${value.toString().replace('.',',')}% к предыдущему периоду`}

async function init(){
  const kioskPath=location.pathname.match(/^\/kiosk(?:\/([\w-]+))?\/?$/);
  try{
    state.config=await api('/config');
    if(kioskPath){state.page='kiosk';state.slug=kioskPath[1]||'central';
      const fragment=location.hash.match(/^#access=([a-zA-Z0-9_-]{30,160})$/);
      if(fragment){sessionStorage.setItem(`osmanx_kiosk_${state.slug}`,fragment[1]);history.replaceState(null,'',location.pathname)}
      state.kioskToken=sessionStorage.getItem(`osmanx_kiosk_${state.slug}`)||null;
      state.store=await api(`/public/store/${encodeURIComponent(state.slug)}`);render();return}
    if(state.config.demo||hasToken())await refresh();else renderLogin();
  }catch(e){state.error=e.message;renderError()}
}
async function refresh(){
  try{
    state.loading=true;
    if(!state.user)state.user=await api('/admin/me',{auth:true});
    if(!state.stores.length)state.stores=await api('/admin/stores',{auth:true});
    if(!state.stores.some(s=>s.slug===state.slug))state.slug=state.stores[0]?.slug||'central';
    state.store=state.stores.find(s=>s.slug===state.slug)||null;
    [state.data,state.stock,state.experiments,state.imports,state.devices,state.team,state.quality,state.posSources]=await Promise.all([
      api(`/admin/dashboard?slug=${encodeURIComponent(state.slug)}&days=${state.days}`,{auth:true}),
      api(`/admin/stock?slug=${encodeURIComponent(state.slug)}`,{auth:true}).then(r=>r.items),
      api(`/admin/experiments?slug=${encodeURIComponent(state.slug)}`,{auth:true}),
      api(`/admin/imports?slug=${encodeURIComponent(state.slug)}`,{auth:true}),
      state.user.role==='viewer'?Promise.resolve([]):api(`/admin/devices?slug=${encodeURIComponent(state.slug)}`,{auth:true}),
      state.user.role==='owner'?api('/admin/team',{auth:true}):Promise.resolve([]),
      api(`/admin/operations/quality?slug=${encodeURIComponent(state.slug)}&days=${state.days}`,{auth:true}),
      state.user.role==='viewer'?Promise.resolve([]):api(`/admin/pos/sources?slug=${encodeURIComponent(state.slug)}`,{auth:true})
    ]);
    state.loading=false;render();
  }catch(e){state.loading=false;state.error=e.message;if(e.message.includes('Требуется вход')||e.message.includes('Сессия'))renderLogin();else renderError()}
}
function renderError(){root.innerHTML=`<div class="login-shell"><div class="panel login-card"><div class="brand">OSMAN<span>X</span></div><div class="brand-sub">RETAIL INTELLIGENCE</div><h1>Не удалось открыть приложение</h1><p>${esc(state.error)}</p><button class="primary-btn" data-action="retry">Повторить ${icon('arrow')}</button><p class="muted">Для локального запуска: <code>OSMANX_DEMO_MODE=1 uvicorn backend.app:app</code></p></div></div>`}
function renderLogin(){root.innerHTML=`<main class="login-shell"><form id="login-form" class="panel login-card"><div class="brand">OSMAN<span>X</span></div><div class="brand-sub">RETAIL INTELLIGENCE</div><h1>Вход в кабинет</h1><p>Защищённый доступ к аналитике магазина. Опросник для покупателей работает по отдельной публичной ссылке.</p><div class="field"><label for="admin-email">Электронная почта</label><input type="email" id="admin-email" name="email" class="input" autocomplete="username" placeholder="owner@company.ru"/></div><div class="field"><label for="admin-pass">Пароль</label><input required autofocus type="password" id="admin-pass" name="password" class="input" autocomplete="current-password" placeholder="Введите пароль"/></div><button type="submit" class="primary-btn" style="width:100%;margin-top:18px">Войти в систему ${icon('arrow')}</button><p><a class="muted" href="/kiosk/central">Открыть публичный терминал опросов</a></p></form></main>`}
function render(){
  if(state.page==='kiosk'){renderKiosk();return}
  if(!state.data){renderError();return}
  document.title='OSMANX · Retail Intelligence';
  document.body.className='app-body';
  root.innerHTML=`<div class="shell">
    <aside class="sidebar ${state.menuOpen?'open':''}"><div class="logo-panel"><div class="brand">OSMAN<span>X</span></div><div class="brand-sub">RETAIL INTELLIGENCE</div></div><div class="side-tag">Рабочая область</div><nav class="nav">${navHtml()}</nav><div class="side-bottom"><div class="connection"><i class="dot"></i> ${state.config.demo?'Демо-среда':'Сервер подключён'}</div><small>© 2026 OSMANX WORLD</small></div></aside>
    <main class="main"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="store-pill">${icon('store',17)}<select id="select-store" aria-label="Выбрать магазин">${state.stores.map(s=>`<option value="${esc(s.slug)}" ${s.slug===state.slug?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div></div><div class="top-right">${featureTag()}<button class="date-pill ${state.days===7?'active':''}" data-days="7">7 дней</button><button class="date-pill ${state.days===30?'active':''}" data-days="30">30 дней</button><button class="icon-btn" title="Открыть опросник" data-action="open-kiosk">${icon('smartphone')}</button><div class="user-pill">OX</div></div></header>${pageHtml()}<footer class="muted" style="padding-top:25px;font-size:10px;line-height:1.7">OSMANX Retail Intelligence · ${esc(state.data.methodology)}</footer></main>
    <nav class="mobile-bottom" aria-label="Быстрая навигация">${[{id:'overview',label:'Главная',ico:'home'},{id:'traffic',label:'Поток',ico:'users'},{id:'demand',label:'Спрос',ico:'shirt'},{id:'feedback',label:'Отзывы',ico:'message'},{id:'actions',label:'Решения',ico:'sparkle'}].map(m=>`<button data-nav="${m.id}" class="${state.page===m.id?'active':''}">${icon(m.ico)}${m.label}</button>`).join('')}</nav>
    <dialog id="entry-dialog"></dialog>
  </div>`;
  if(state.menuOpen){const aside=document.querySelector('.sidebar');aside?.addEventListener('mouseleave',()=>{if(innerWidth>890)return;state.menuOpen=false;aside.classList.remove('open')},{once:true})}
}
function pageHtml(){switch(state.page){case'overview':return overview();case'traffic':return traffic();case'zones':return zonesPage();case'demand':return demand();case'stock':return stock();case'feedback':return feedback();case'actions':return actions();case'integrations':return integrations();case'monitor':return monitoring();case'settings':return settings();case'team':return teamPage();default:return overview()}}
function dailyBars(items){const max=Math.max(1,...items.map(x=>x.visitors));return `<div class="daily-bars" role="img" aria-label="Входы по дням">${items.map(d=>`<div class="daily-day" title="${d.date}: ${d.visitors} входов, ${d.purchases} чеков"><div class="daily-col" style="height:${Math.max(2,100*d.visitors/max)}%"><i style="height:${Math.max(0,100*d.purchases/Math.max(1,d.visitors))}%"></i></div><small>${d.date.slice(8)}</small></div>`).join('')}</div>`}
function qualityPanel(s){return `<div class="quality-box"><p class="tip">Режим подсчёта: <strong>${esc({combined:'все источники (возможны дубли)',auto:'автовыбор источника',manual:'только ручной',sensor:'только датчики'}[s.traffic_mode]||s.traffic_mode)}</strong></p><div class="quality-head"><span>${icon('shield',19)} Источники входов</span><b>${s.visits.length} типов</b></div>${s.visits.map(v=>`<div class="quality-line"><span>${esc(v.source)}</span><b>${integer(v.count)} входов</b></div>`).join('')||'<p class="tip">Подключите датчик входов или ручной учёт.</p>'}<div class="quality-head" style="margin-top:17px"><span>${icon('bag',19)} Источники чеков</span></div>${s.sales.map(v=>`<div class="quality-line"><span>${esc(v.source)}</span><b>${integer(v.count)} чеков</b></div>`).join('')}${s.warnings.map(w=>`<p class="quality-warning">${icon('alert',16)} ${esc(w)}</p>`).join('')||'<p class="quality-ok">Критичных несоответствий не обнаружено в доступных данных.</p>'}</div>`}
function stockOpportunities(items){return items.length?`<div class="opportunity-list">${items.map(d=>`<div class="opportunity"><span class="opportunity-icon">${icon('layers',21)}</span><div><strong>${esc(d.product)} · ${esc(d.size||'—')}</strong><p>${d.matches.map(m=>`${esc(m.store_name)}: ${integer(m.quantity)} шт.`).join(' · ')}</p><small>Наличие требует подтверждения у филиала перед резервом</small></div><button class="secondary-btn small-btn" data-matches="${d.demand_id}">Проверить</button></div>`).join('')}</div>`:miniEmpty('layers','Нет совпадений','При появлении остатков в других филиалах они отобразятся здесь.')}
function surveyTagSummary(items,key,labels){const counts={};for(const item of items){let tags=[];try{tags=JSON.parse(item[key]||'[]')}catch{}for(const t of tags)counts[t]=(counts[t]||0)+1}return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k,n])=>`<div class="quality-line"><span>${esc(labels[k]||k)}</span><b>${integer(n)}</b></div>`).join('')||'<p class="tip">Пока нет отмеченных ответов.</p>'}

function heatMap(zones){if(!zones.length)return miniEmpty('grid','Нет измерений по зонам','Создайте зону в настройках карты, затем подключите обезличенный датчик.');const max=Math.max(1,...zones.map(z=>z.count));return `<div class="floor-map"><div class="floor-wall wall-h a"></div><div class="floor-wall wall-v b"></div><div class="floor-wall wall-h c"></div><div class="floor-wall wall-v d"></div><div class="floor-caption">СХЕМА ЗОН · НЕ ПЛАН ПОМЕЩЕНИЯ</div>${zones.map(z=>{const ratio=z.count/max;return `<div class="zone-point" style="left:${z.x}%;top:${z.y}%;--power:${Math.max(.28,ratio).toFixed(2)}" title="${esc(z.name)}: ${integer(z.count)} событий"><span class="heat-spot"></span><span class="zone-name">${esc(z.name)}</span><b>${integer(z.count)}</b></div>`}).join('')}</div><div class="zone-legend"><span>Меньше событий</span><div></div><span>Больше событий</span></div><p class="tip" style="margin-top:13px">Это тепловая карта зарегистрированных событий по зонам — не отслеживание перемещений отдельных людей. Количество событий может быть больше числа посетителей.</p>`}
function zonesPage(){const d=state.data;return `${heading('Тепловая карта магазина','События по зонам: только обезличенные счётчики без распознавания лиц.',`<button class="primary-btn" data-dialog="zone">${icon('plus')} Добавить зону</button>`)}<div class="content-grid"><div class="span-8">${pane('Активность по зонам',heatMap(d.zones))}</div><div class="span-4">${pane('Подключение датчиков',`<div class="info-stack"><div class="info-line"><span>Зон создано</span><b>${integer(d.zones.length)}</b></div><div class="info-line"><span>Событий за период</span><b>${integer(d.zones.reduce((n,z)=>n+z.count,0))}</b></div></div><p class="tip" style="margin-top:15px">Настоящая карта появится после настройки зон в координатах помещения и подключения датчика. Демонстрационные данные не являются измерениями магазина.</p>`)}</div><div class="span-12">${pane('Схема API для интегратора',`<pre class="code">POST /api/ingest/v2/zones
X-OSMANX-Device: &lt;ID устройства&gt;\nX-OSMANX-Timestamp: &lt;Unix UTC&gt;\nX-OSMANX-Signature: &lt;HMAC-SHA256&gt;
{ "slug": "${esc(state.slug)}", "zone_code": "entrance",
  "quantity": 4, "external_id": "zone-event-0001",
  "occurred_at": "2026-11-08T14:00:00Z" }</pre><p class="tip" style="margin-top:13px">Датчик должен отдавать количество событий, а не видео, фотографии или идентификаторы людей. Запись с тем же external_id не учитывается дважды.</p>`)}</div></div>`}
function overview(){const d=state.data;
return `${heading('Обзор бизнеса','Понимайте спрос. Находите точки роста. Принимайте решения на основе данных.',`<button class="secondary-btn" data-action="open-kiosk">${icon('smartphone')} Экран опроса</button><button class="primary-btn" data-dialog="demand">${icon('plus')} Записать запрос</button>`)}
<div class="hero-ribbon"><div><strong>Принимайте решения на основе подтверждённых фактов</strong><p>Причины отказов — гипотезы, пока не проверены данными и экспериментами.</p></div><button class="btn-link" data-nav="actions">Перейти к рекомендациям →</button></div>
<div class="content-grid">
 <div class="span-3">${cardStat('Посетители',integer(d.visitors),'users',d.delta_visitors,'входов')}</div>
 <div class="span-3">${cardStat('Покупки',integer(d.purchases),'bag',d.delta_purchases,'чеков')}</div>
 <div class="span-3">${cardStat('Конверсия',d.conversion.toString().replace('.',',')+'%','target',d.delta_conversion_pp,'чеков / входов')}</div>
 <div class="span-3">${cardStat('Выручка',money(d.revenue),'chart',d.delta_revenue,'по чекам',true)}</div>
 <div class="span-7">${pane('Посещаемость и покупки по часам',`<div class="legend"><span><b class="blue-dot"></b> Входы</span><span><b class="red-dot"></b> Покупки</span></div>${lineChart(d.hourly)}<p class="tip" style="margin-top:10px">Суммы событий по часам за ${d.period_days} дней.</p>`)}</div>
 <div class="span-5">${pane('Почему не совершили покупку?',donut(d.reasons)+`<div class="card-help">Данные добровольных опросов; не все покупатели отвечают.</div>`)}</div>
 <div class="span-6">${pane('Самый частый неудовлетворённый спрос',topDemand(d.top_demand,4))}</div>
 <div class="span-6">${pane('Рекомендации по действиям',recs(d.recommendations,3))}</div>
 <div class="span-12">${pane('Конверсия по дням',`${dailyBars(d.daily)}<p class="tip" style="margin-top:12px">Дни рассчитываются в часовом поясе филиала (${esc(d.timezone)}). Красная линия — доля чеков от входов.</p>`)}</div>
 <div class="span-6">${pane('Потенциально доступные товары в других филиалах',stockOpportunities(d.stock_matches))}</div>
 <div class="span-6">${pane('Качество данных',qualityPanel(d.sources))}</div>
 <div class="span-12">${pane('Тепловая карта активности магазина',heatMap(d.zones))}</div>
 <div class="span-7">${pane('События пути покупателя',funnel(d))}</div>
 <div class="span-5">${pane('Качество обратной связи',`<div class="metrics-row"><div class="micro-card"><span>Опросы</span><b>${integer(d.surveys_count)}</b></div><div class="micro-card"><span>Средняя оценка</span><b>${d.rating?d.rating.toString().replace('.',','):'—'} / 5</b></div><div class="micro-card"><span>Новые запросы</span><b>${integer(d.top_demand.reduce((a,v)=>a+v.count,0))}+</b></div></div><div class="separated"><a class="secondary-btn" href="/kiosk/${encodeURIComponent(state.slug)}" target="_blank" rel="noopener">${icon('smartphone')} Открыть терминал</a></div>`)}</div>
</div>`}
function topDemand(items,limit=6){return items.length?`<div class="demand-list">${items.slice(0,limit).map(d=>`<div class="demand-item"><div class="product-box">${icon('shirt')}</div><div class="demand-main"><strong>${esc(d.product)}</strong><small>Размер ${esc(d.size||'не указан')} · ${esc(d.color||'без цвета')}</small></div><div><div class="count monospace">${integer(d.count)}</div><small class="muted">запросов</small></div></div>`).join('')}</div>`:miniEmpty('shirt','Пока нет запросов','Добавьте первый запрос на отсутствующий товар или размер.')}
function recs(items,limit=6){return `<div class="rec-list">${items.slice(0,limit).map(r=>`<article class="rec-item"><div class="rec-symbol">${icon(r.type==='demand'?'shirt':r.type==='feedback'?'message':r.type==='traffic'?'chart':'sparkle')}</div><div><strong>${esc(r.title)}</strong><p>${esc(r.text)}</p></div></article>`).join('')}</div>`}
function funnel(d){const stages=[{text:'Вошли в магазин',value:d.visitors},{text:'События интереса',value:d.signals.interest||0},{text:'Примерки (события)',value:d.signals.fitting||0},{text:'Кассовые чеки',value:d.purchases}];return `<div class="funnel">${stages.map(s=>`<div class="funnel-step"><span>${esc(s.text)}</span><span>${integer(s.value)}</span></div>`).join('')}</div><p class="tip" style="margin-top:16px">Этапы могут фиксироваться разными источниками и не связаны с конкретными людьми. Диаграмма не является сквозной воронкой.</p>`}
function traffic(){const d=state.data;return `${heading('Посетители и конверсия','Реальные события входов, чеков и примерок, без распознавания лиц.',`<button class="secondary-btn" data-export="visits">${icon('download')} CSV</button><button class="primary-btn" data-dialog="entry">${icon('plus')} Добавить событие</button>`)}
<div class="content-grid">
 <div class="span-3">${cardStat('Входы',integer(d.visitors),'users',d.delta_visitors,'событий')}</div><div class="span-3">${cardStat('Покупки',integer(d.purchases),'bag',d.delta_purchases,'чеков')}</div><div class="span-3">${cardStat('Конверсия',d.conversion+'%','target',d.delta_conversion_pp,'условная')}</div><div class="span-3">${cardStat('Средний чек',money(d.avg_receipt),'tag',null,'по чекам')}</div>
 <div class="span-8">${pane('Поток по часам',`<div class="legend"><span><b class="blue-dot"></b> Входы</span><span><b class="red-dot"></b> Покупки</span></div>${barChart(d.hourly)}<p class="tip" style="margin-top:13px">Часы в поясе ${esc(d.timezone)}; суммы за ${d.period_days} дней.</p>`)}</div>
 <div class="span-4">${pane('Проверка источников',qualityPanel(d.sources))}</div>
 <div class="span-12">${pane('Активность по дням',dailyBars(d.daily))}</div>
 <div class="span-12">${pane('Быстрый ввод событий',`<div class="inline-actions"><button class="secondary-btn" data-quick="entry">${icon('users')} +1 вход</button><button class="secondary-btn" data-dialog="sale">${icon('bag')} Новая продажа</button><button class="secondary-btn" data-quick="interest">${icon('heart')} Интерес</button><button class="secondary-btn" data-quick="fitting">${icon('shirt')} Примерка</button></div><p class="tip" style="margin-top:16px">Не дублируйте вручную события, которые уже передаёт датчик или касса.</p>`)}</div>
</div>`}
function demand(){const d=state.data;const list=d.latest_demand;return `${heading('Невидимый спрос','Товары, размеры и цвета, которые спрашивали, но не нашли.',`<button class="secondary-btn" data-export="demand">${icon('download')} CSV</button><button class="primary-btn" data-dialog="demand">${icon('plus')} Новый запрос</button>`)}<div class="content-grid">
 <div class="span-3">${cardStat('Запросов',integer(d.top_demand.reduce((a,v)=>a+v.count,0)),'shirt',null,'по востребованным позициям')}</div>
 <div class="span-3">${cardStat('Продаж подтверждено',integer(d.verified_sales_from_demand),'check',null,'по связанным чекам')}</div>
 <div class="span-6">${pane('Важное ограничение',`<p class="tip">Каждый запрос — повод проверить наличие и спрос, но не гарантированная потеря денег. Подтверждённой продажей считается только запрос, привязанный к настоящему чеку этого филиала.</p>`)}</div>
 <div class="span-6">${pane('Чаще всего спрашивают',topDemand(d.top_demand,6))}</div>
 <div class="span-6">${pane('Совпадения в других магазинах',stockOpportunities(d.stock_matches))}</div>
 <div class="span-12">${pane('Журнал обращений',list.length?`<div class="panel-overflow"><table class="list-table"><thead><tr><th>Товар</th><th>Размер</th><th>Цвет</th><th>Время</th><th>Статус</th><th>Другие филиалы</th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${esc(r.product)}</strong>${r.sale_id?`<span class="tag mini-tag">Чек №${r.sale_id}</span>`:''}</td><td>${esc(r.size||'—')}</td><td>${esc(r.color||'—')}</td><td>${shortDate(r.created_at)}</td><td><select class="select" style="width:150px;padding:7px" data-demand-id="${r.id}" aria-label="Статус запроса">${Object.entries(statusLabels).map(([key,label])=>`<option value="${key}" ${r.status===key?'selected':''}>${label}</option>`).join('')}</select></td><td><div class="inline-actions"><button class="secondary-btn small-btn" data-matches="${r.id}">Найти размер</button>${r.sale_id?`<span class="status converted">Чек подтверждён</span>`:`<button class="secondary-btn small-btn" data-confirm-demand="${r.id}">Связать чек</button>`}</div></td></tr>`).join('')}</tbody></table></div>`:miniEmpty('shirt','Нет запросов','Добавьте запрос на отсутствующую модель.') )}</div>
</div>`}
function stock(){const items=state.stock;const zero=items.filter(x=>x.quantity===0).length;return `${heading('Остатки и доступность','Сравнение фактических остатков по филиалам — без вымышленной синхронизации с 1С.',`<button class="secondary-btn" data-export="inventory">${icon('download')} CSV</button><button class="primary-btn" data-dialog="stock">${icon('plus')} Добавить товар</button>`)}
<div class="content-grid">
 <div class="span-3">${cardStat('Артикулов',integer(items.length),'layers',null,'в текущем филиале')}</div>
 <div class="span-3">${cardStat('Нет в наличии',integer(zero),'alert',null,'нулевой остаток')}</div>
 <div class="span-6">${pane('Импорт для одной точки',`<p class="tip">Ручное добавление и JSON-импорт не подключают 1С автоматически. Повторный артикул обновляет остаток — операция идемпотентна.</p><div class="separated"><button class="secondary-btn" data-dialog="stock-batch">${icon('download')} Импорт набора товаров</button></div>`)}</div>
 <div class="span-12">${pane('Каталог текущего филиала',items.length?`<div class="panel-overflow"><table class="list-table"><thead><tr><th>Артикул</th><th>Товар</th><th>Размер</th><th>Цвет</th><th>Остаток</th><th>Источник</th><th>Обновлено</th></tr></thead><tbody>${items.map(x=>`<tr><td class="nowrap">${esc(x.sku)}</td><td><strong>${esc(x.product)}</strong></td><td>${esc(x.size||'—')}</td><td>${esc(x.color||'—')}</td><td><span class="status ${x.quantity===0?'open':'converted'}">${integer(x.quantity)} шт.</span></td><td>${esc(x.source)}</td><td>${shortDate(x.updated_at)}</td></tr>`).join('')}</tbody></table></div>`:miniEmpty('layers','Каталог пуст','Загрузите остатки или внесите первый товар.'))}</div>
</div>`}
function feedback(){const d=state.data;return `${heading('Опросы и обратная связь','Мнения покупателей, причины отказов и добровольная оценка магазина.',`<button class="secondary-btn" data-export="surveys">${icon('download')} CSV</button><button class="primary-btn" data-action="open-kiosk">${icon('smartphone')} Открыть терминал</button>`)}<div class="content-grid">
 <div class="span-3">${cardStat('Опросов',integer(d.surveys_count),'clipboard',null)}</div><div class="span-3">${cardStat('Средняя оценка',(d.rating||0).toString().replace('.',',')+'/5','star',null)}</div><div class="span-6">${pane('Причины ухода без покупки',donut(d.reasons))}</div>
 <div class="span-6">${pane('Что понравилось (последние 30 ответов)',surveyTagSummary(d.latest_surveys,'liked_tags',likedOptions))}</div>
 <div class="span-6">${pane('Что улучшить (последние 30 ответов)',surveyTagSummary(d.latest_surveys,'improve_tags',improveOptions))}</div>
 <div class="span-12">${pane('Последние отзывы',d.latest_surveys.length?`<div class="panel-overflow"><table class="list-table"><thead><tr><th>Дата</th><th>Оценка</th><th>Покупка</th><th>Причина</th><th>Комментарий</th><th>Предложение</th></tr></thead><tbody>${d.latest_surveys.map(x=>`<tr><td class="nowrap">${shortDate(x.created_at)}</td><td class="nowrap"><span class="red">${'★'.repeat(x.rating)}</span></td><td>${x.purchased?'Да':'Нет'}</td><td>${esc(reasonLabels[x.reason]||'—')}</td><td>${esc(x.liked||'—')}</td><td>${esc(x.suggestion||'—')}</td></tr>`).join('')}</tbody></table></div>`:miniEmpty('message','Ответов пока нет','Покажите опросник посетителям.') )}</div>
 <div class="span-7">${pane('Выдача бонусов',`<p class="tip">Бонусный код включается только владельцем. Покупатель показывает его сотруднику, который вручную проверяет и погашает код. Без автоматического обещания скидки или связи с кассой.</p><form id="redeem-form" class="form-card"><div class="field"><label>Код покупателя</label><input class="input" name="code" placeholder="OX-1234ABCD" required maxlength="40" autocomplete="off" /></div><button class="secondary-btn" type="submit">${icon('check')} Проверить и погасить</button></form>`)}</div>
 <div class="span-5">${pane('Публичная анкета',`<p class="tip">Четыре простых вопроса: оценка, покупка, что понравилось, что улучшить. Без имени, телефона или отслеживания личности.</p><div class="separated"><button class="secondary-btn" data-action="copy-kiosk">${icon('link')} Скопировать ссылку</button></div>`)}</div>
</div>`}
function actions(){const d=state.data;return `${heading('Рекомендации и пилоты','От наблюдения к проверяемому решению — без недоказанных обещаний прибыли.',`<button class="primary-btn" data-dialog="experiment">${icon('plus')} Новая гипотеза</button>`)}
<div class="content-grid">
 <div class="span-7">${pane('Гипотезы по данным магазина',recs(d.recommendations)+`<div class="separated note">Рекомендации создаёт прозрачный движок правил. Это не прогноз AI и не автоматическое принятие управленческих решений.</div>`)}</div>
 <div class="span-5">${pane('Сценарий улучшения конверсии',`<div class="form-card"><p class="tip">Сценарий, не прогноз. Для прибыли учитывайте затраты, маржу и качество исходных данных.</p><div class="field"><label for="scenario-pp">Прирост конверсии, п.п.</label><input id="scenario-pp" type="range" min="0" max="10" step="0.5" value="2" style="width:100%;accent-color:#f43856"/><b id="scenario-pp-label">2 п.п.</b></div><div class="field"><label for="scenario-margin">Валовая маржа, %</label><input id="scenario-margin" type="number" value="45" min="1" max="100" step="1" class="input"/></div><div class="micro-card"><span>Условная доп. выручка</span><b id="scenario-revenue">—</b></div><div class="micro-card"><span>Условная доп. валовая прибыль до затрат</span><b id="scenario-profit">—</b></div></div>`)}</div>
 <div class="span-12">${pane('Доска экспериментов',state.experiments.length?`<div class="experiment-list">${state.experiments.map(e=>`<article class="experiment-item"><div class="experiment-content"><span class="tag mini-tag">${esc({planned:'План',running:'Проводится',finished:'Завершено',cancelled:'Отменено'}[e.status])}</span><h3>${esc(e.title)}</h3><p>${esc(e.hypothesis)}</p><small>Метрика: ${esc(e.metric)} · База: ${e.baseline??'не задана'} · Результат: ${e.result??'не измерен'}</small>${e.notes?`<p class="muted">${esc(e.notes)}</p>`:''}</div><button class="secondary-btn small-btn" data-experiment-id="${e.id}">Изменить</button></article>`).join('')}</div>`:miniEmpty('target','Нет гипотез','Создайте первый двухнедельный пилот.') )}</div>
 <div class="span-12">${pane('Последовательность пилота',`<div class="metrics-row"><div class="micro-card"><span>Этап 1</span><b>База</b><span>Замеряем исходный уровень</span></div><div class="micro-card"><span>Этап 2</span><b>Изменение</b><span>Тестируем одно действие</span></div><div class="micro-card"><span>Этап 3</span><b>Проверка</b><span>Сравниваем и оцениваем затраты</span></div></div>`)}</div>
</div>`}
function monitoring(){const q=state.quality||{};const v=q.visits||{total:0,sources:[]},sales=q.sales||{total:0,sources:[]};return `${heading('Контроль качества данных','Предупреждения говорят о полноте измерений, а не доказывают упущенную выручку.',`<button class="secondary-btn" data-action="refresh-monitor">${icon('activity')} Обновить</button>`)}<div class="content-grid">
<div class="span-3">${cardStat('Зафиксировано входов',integer(v.total),'users',null,'период '+state.days+' дней')}</div>
<div class="span-3">${cardStat('Чеков',integer(sales.total),'bag',null,'из доступных источников')}</div>
<div class="span-3">${cardStat('Опросов',integer(q.surveys?.total),'clipboard',null,'добровольных')}</div>
<div class="span-3">${cardStat('Незакрытых запросов',integer(q.unresolved_demand),'shirt',null,'запросов')}</div>
<div class="span-7">${pane('Предупреждения',q.warnings?.length?q.warnings.map(w=>`<div class="quality-warning"><div><strong>${esc(w.code)}</strong><p>${esc(w.message)}</p></div></div>`).join(''):'<p class="quality-ok">Известных нарушений контроля данных нет.</p>')}</div>
<div class="span-5">${pane('Источники информации',`<p class="tip">Показатели не позволяют идентифицировать посетителя.</p>${[...v.sources,...sales.sources].map(x=>`<div class="quality-line"><span>${esc(x.source)}</span><b>${integer(x.total)} событий</b></div>`).join('')||'<p class="tip">Данные отсутствуют.</p>'}`)}</div>
<div class="span-6">${pane('Подписанные датчики',q.devices?.length?q.devices.map(x=>`<div class="quality-line"><span><strong>${esc(x.name)}</strong><small style="display:block">${esc(x.kind)} · ${x.active?'Активен':'Отключён'}</small></span><small>Последний сигнал: ${x.last_seen?shortDate(x.last_seen):'ещё нет'}</small></div>`).join(''):miniEmpty('plug','Нет датчиков','Зарегистрируйте устройство в интеграциях.'))}</div>
<div class="span-6">${pane('Кассовые подключения',q.pos_sources?.length?q.pos_sources.map(x=>`<div class="quality-line"><span><strong>${esc(x.name)}</strong><small style="display:block">${x.active?'Активно':'Отключено'}</small></span><small>Последний чек: ${x.last_seen?shortDate(x.last_seen):'ещё нет'}</small></div>`).join(''):miniEmpty('bag','Нет кассового источника','Можно подключить интегратор по подписанному POS API.'))}</div>
<div class="span-12">${pane('Методология',`<p class="tip">Визиты считаются только по тем источникам, которые подключены. Если одновременно вручную и датчиком регистрируется один вход, показатели могут дублироваться. Для проверки причин отказов нужны опросы, наблюдения и эксперименты. Нет прямого распознавания личности по видео.</p>`)}</div></div>`}

function integrations(){const d=state.devices||[];const p=state.pendingImport;const writable=['owner','manager'].includes(state.user?.role);return `${heading('Интеграции и импорт','Подписанные устройства и предварительная проверка данных до записи.')}
<div class="content-grid">
 <div class="span-7">${pane('Безопасный импорт из CSV/1С через подготовленный JSON',`<p class="tip">Для экспорта из 1С или кассы сначала сопоставьте поля с форматом OSMANX. Это не прямая интеграция. Проверка покажет новые, изменённые и конфликтующие записи — без изменения данных магазина.</p><form id="import-preview-form" class="form-card"><div class="field"><label>Тип данных</label><select class="select" name="kind"><option value="pos">Продажи и чеки</option><option value="inventory">Складские остатки</option></select></div><div class="field"><label>Массив JSON</label><textarea name="records" rows="6" class="textarea" spellcheck="false" required placeholder='[{"external_id":"receipt-100","amount_rub":5400,"occurred_at":"2026-11-08T12:00:00+03:00"}]'></textarea></div><button class="primary-btn" type="submit" ${!writable?'disabled':''}>${icon('check')} Проверить импорт</button></form>${p?`<div class="import-preview"><h3>Предпросмотр · ${esc(p.kind)}</h3><div class="metrics-row"><div class="micro-card"><span>Добавить</span><b>${integer(p.preview.added)}</b></div><div class="micro-card"><span>Изменить</span><b>${integer(p.preview.updated)}</b></div><div class="micro-card"><span>Уже есть</span><b>${integer(p.preview.unchanged)}</b></div></div>${p.preview.conflicts.length?`<p class="quality-warning">Конфликты ID: ${p.preview.conflicts.map(esc).join(', ')}</p>`:''}<button class="primary-btn" data-action="import-apply" ${!p.preview.valid?'disabled':''}>${icon('check')} Подтвердить и применить</button></div>`:''}`)}</div>
 <div class="span-5">${pane('Устройства филиала',`<p class="tip">Каждый счётчик получает отдельный секрет с подписью HMAC, ограниченный одним филиалом. Секрет показывается только при создании или замене.</p><div class="separated">${d.map(x=>`<div class="quality-line"><span><strong>${esc(x.name)}</strong><small style="display:block">${esc(x.kind)} · ${x.active?'Работает':'Отключён'}</small></span>${writable?`<span class="inline-actions"><button class="secondary-btn small-btn" data-device-rotate="${esc(x.public_id)}">Сменить ключ</button><button class="secondary-btn small-btn" data-device-revoke="${esc(x.public_id)}">Отключить</button></span>`:''}</div>`).join('')||'<p class="tip">Устройств ещё нет.</p>'}</div>${writable?`<button class="secondary-btn" data-dialog="device">${icon('plus')} Добавить устройство</button>`:''}`)}</div>
 <div class="span-12">${pane('Что подключено фактически',`<div class="metrics-row"><div class="micro-card"><span>Опросы на планшете</span><b>Работает</b></div><div class="micro-card"><span>Импорт файлов</span><b>С проверкой</b></div><div class="micro-card"><span>POS API</span><b>${state.posSources?.some(x=>x.accepted_events>0)?'Есть чеки':'Нет данных'}</b></div></div><div class="separated note">Датчики используют POST /api/ingest/v2/traffic или /api/ingest/v2/zones. Заголовки: X-OSMANX-Device, X-OSMANX-Timestamp (секунды Unix), X-OSMANX-Signature (HMAC-SHA256 по timestamp + «\n» + device_id + «\n» + исходные байты JSON). Прямой камерный захват и распознавание лиц не реализованы.</div>`)}</div>
 <div class="span-12">${pane('Подписанные кассовые подключения',`<p class="tip">Доступен HTTP API для вашего интегратора с HMAC-подписью чеков. Это не готовое подключение конкретной кассы или 1С.</p>${(state.posSources||[]).map(x=>`<div class="quality-line"><span><strong>${esc(x.name)}</strong><small style="display:block">${esc(x.public_id)} · ${x.active?'Активно':'Отключено'} · Последний чек: ${x.last_seen?shortDate(x.last_seen):'нет'}</small></span>${writable?`<span class="inline-actions"><button class="secondary-btn small-btn" data-pos-rotate="${esc(x.public_id)}">Ключ</button><button class="secondary-btn small-btn" data-pos-revoke="${esc(x.public_id)}">Отключить</button></span>`:''}</div>`).join('')||'<p class="tip">Источники пока не подключены.</p>'}${writable?`<form class="form-card" id="pos-source-form"><div class="field"><label>Название кассы или интеграции</label><input class="input" name="name" required minlength="2" maxlength="100" placeholder="Касса Центральный"/></div><button class="secondary-btn" type="submit">${icon('plus')} Создать источник и ключ</button></form>`:''}<div class="separated note">POST /api/ingest/pos; подпись зависит от точных байт JSON, ID источника и Unix-времени. Дубли не создают повторных продаж.</div>`)}</div>
 <div class="span-12">${pane('Журнал импорта',state.imports.length?`<div class="panel-overflow"><table class="list-table"><thead><tr><th>Создан</th><th>Тип</th><th>Статус</th><th>Идентификатор</th></tr></thead><tbody>${state.imports.map(x=>`<tr><td>${shortDate(x.created_at)}</td><td>${esc(x.kind)}</td><td>${esc(x.status==='applied'?'Применён':'Ожидает подтверждения')}</td><td>${esc(x.batch_key.slice(0,16))}…</td></tr>`).join('')}</tbody></table></div>`:miniEmpty('database','Нет импортов','Проверьте первый файл перед записью.'))}</div>
</div>`}
function teamPage(){if(state.user?.role!=='owner')return heading('Сотрудники','Только владелец организации может управлять доступом.');return `${heading('Команда и права','Каждый сотрудник видит только назначенные магазины и доступные ему действия.',`<button class="primary-btn" data-dialog="team">${icon('plus')} Пригласить сотрудника</button>`)}<div class="content-grid"><div class="span-12">${pane('Аккаунты организации',`<div class="panel-overflow"><table class="list-table"><thead><tr><th>Сотрудник</th><th>Роль</th><th>Филиалы</th><th>Статус</th><th>Управление</th></tr></thead><tbody>${state.team.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small style="display:block" class="muted">${esc(u.email)}</small></td><td>${esc({owner:'Владелец',manager:'Управляющий',analyst:'Аналитик',viewer:'Наблюдатель'}[u.role])}</td><td>${esc(u.role==='owner'?'Все филиалы':u.stores.join(', '))}</td><td>${u.active?'Активен':'Отключён'}</td><td>${u.role!=='owner'?`<button class="secondary-btn small-btn" data-team-toggle="${u.id}">${u.active?'Отключить':'Активировать'}</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="span-12">${pane('Модель доступа',`<p class="tip">Владелец управляет филиалами и сотрудниками. Управляющий вносит продажи, остатки и гипотезы в своих филиалах. Аналитик смотрит отчёты, наблюдатель только читает. Новые аккаунты получают отдельный пароль и независимые сессии.</p>`)}</div></div>`}

function settings(){const st=state.store||{};return `${heading('Настройки магазина','Отдельные параметры филиала, опросника и подтверждения бонусов.',`<button class="secondary-btn" data-dialog="new-store">${icon('plus')} Новый филиал</button>`)}<div class="content-grid">
 <div class="span-7">${pane('Карточка магазина и анкета',`<form id="store-form" class="form-card"><div class="field"><label>Название филиала</label><input class="input" name="name" value="${esc(st.name)}" maxlength="100" required/></div><div class="field"><label>Описание</label><input class="input" name="subtitle" value="${esc(st.subtitle)}" maxlength="150"/></div><div class="field"><label>Часовой пояс</label><select class="select" name="timezone">${['Europe/Moscow','Europe/Stockholm','Europe/London','Asia/Dubai','UTC'].map(z=>`<option ${z===(st.timezone||'Europe/Moscow')?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Подпись после анкеты</label><input class="input" name="incentive" value="${esc(st.incentive||'')}" maxlength="160" placeholder="Спасибо, что помогаете нам стать лучше"/></div><label class="toggle-line"><input type="checkbox" name="reward_enabled" ${st.reward_enabled?'checked':''}/><span>Включить выдачу уникальных кодов после опроса</span></label><div class="field"><label>Текст бонуса (не гарантия скидки)</label><input class="input" name="reward_label" value="${esc(st.reward_label||'')}" maxlength="100" placeholder="Бонус при предъявлении кода сотруднику"/></div><p class="tip">Код действителен 7 дней и погашается вручную. Коды ограничены дневным лимитом и могут закончиться.</p><div class="field"><label>Максимум бонусов в день (0 — выключить)</label><input class="input" name="reward_daily_limit" type="number" min="0" max="200" value="${st.reward_daily_limit??20}" /></div><div class="field"><label>Срок хранения ответов, дней</label><input class="input" name="survey_retention_days" type="number" min="7" max="365" value="${st.survey_retention_days??90}" /></div><div class="field"><label>Источник входов для конверсии</label><select class="select" name="traffic_mode">${Object.entries({auto:'Автовыбор: датчик, затем ручной',sensor:'Только датчики',manual:'Только ручные входы',combined:'Все источники (возможны повторы)'}).map(([key,label])=>`<option value="${key}" ${st.traffic_mode===key?'selected':''}>${label}</option>`).join('')}</select></div><button class="primary-btn" type="submit">${icon('check')} Сохранить настройки</button></form>`)}</div>
 <div class="span-5">${pane('Ссылка на терминал',`<p class="tip">Откройте адрес на планшете у выхода. Физический терминал и HTTPS потребуются при установке в магазине.</p><div class="code" id="kiosk-url" style="margin:15px 0">${esc(location.origin+'/kiosk/'+state.slug)}</div><div class="inline-actions"><button class="secondary-btn" data-action="copy-kiosk">${icon('link')} Скопировать</button><button class="secondary-btn" data-action="open-kiosk">${icon('smartphone')} Открыть</button></div><div class="separated note">Демонстрационный режим не защищает административные данные. Для пилота требуется HTTPS, секреты и независимая проверка оборудования.</div>`)}</div>
 <div class="span-12">${pane('Защита терминала опросов',`<p class="tip">${st.kiosk_required?'Терминал требует приватный ключ.':'Открытая анкета: любой посетитель с ссылкой может отправить ответ.'} Создайте персональную ссылку для планшета и передайте её сотруднику. Секрет хранится в сессии планшета, а не передаётся в адресе HTTP-запроса.</p><div class="inline-actions"><button class="primary-btn" data-action="pair-kiosk">${icon('shield')} ${st.kiosk_required?'Перевыпустить ключ':'Защитить и привязать'}</button>${st.kiosk_required?`<button class="secondary-btn" data-action="unpair-kiosk">Выключить защиту</button>`:''}</div>`)}</div>
 ${!state.config.demo?`<div class="span-12">${pane('Пароль и сессии',`<form id="change-password-form" class="form-card"><div class="field"><label>Текущий пароль</label><input class="input" name="current_password" type="password" required autocomplete="current-password"/></div><div class="field"><label>Новый пароль (12+ символов)</label><input class="input" name="new_password" type="password" minlength="12" required autocomplete="new-password"/></div><button class="secondary-btn" type="submit">Сменить пароль</button></form><div class="separated"><button class="ghost-btn" data-action="logout-all">${icon('logout')} Завершить все сессии</button></div>`)}</div>`:''}
 ${!state.config.demo?`<div class="span-12">${pane('Управление сессией',`<button class="ghost-btn" data-action="logout">${icon('logout')} Выйти из кабинета</button>`)}</div>`:''}
</div>`}
function renderKiosk(){
  document.title='OSMANX · Ваше мнение';document.body.className='kiosk-body';
  const st=state.store||{name:'Магазин',reward_enabled:false};
  if(st.kiosk_required&&!state.kioskToken){root.innerHTML=`<div class="login-shell kiosk-lock"><form id="kiosk-access-form" class="panel login-card"><div class="brand">OSMAN<span>X</span></div><div class="brand-sub">RETAIL INTELLIGENCE</div><h1>Подключение терминала</h1><p>Этот планшет должен быть привязан управляющим. Откройте специальную ссылку привязки либо введите токен.</p><div class="field"><label>Ключ терминала</label><input class="input" name="token" autocomplete="off" required minlength="30"/></div><button class="primary-btn" type="submit">Подключить опросник</button></form></div>`;return}
  const k=state.kiosk,step=state.kioskStep;let body='',bottom='';
  const tagButtons=(options,kind,selected)=>`<div class="kiosk-tags">${Object.entries(options).map(([key,label])=>`<button type="button" class="kiosk-chip ${selected.includes(key)?'selected':''}" data-kiosk-tag="${key}" data-kiosk-tag-kind="${kind}" aria-pressed="${selected.includes(key)}">${selected.includes(key)?icon('check',16):icon('plus',16)} ${esc(label)}</button>`).join('')}</div>`;
  if(step===0){
    body=`<div class="kiosk-hero-badge">${icon('gift',17)} ВАШЕ МНЕНИЕ ВАЖНО</div><h2>Помогите нам<br><span class="red">стать лучше.</span></h2><p>Всего 4 коротких вопроса. Расскажите, что понравилось и чего вам не хватило — это поможет улучшить магазин.</p><div class="kiosk-intro-metrics"><span>${icon('clock',21)} 15–25 секунд</span><span>${icon('shield',21)} Без регистрации</span></div>${st.reward_enabled?`<div class="kiosk-incentive">${icon('gift',20)} Возможный бонус: ${esc(st.reward_label||'бонус магазина')}<small>Код проверяется сотрудником по условиям акции</small></div>`:''}`;
    bottom=`<button class="primary-btn" data-kiosk="start">Начать опрос ${icon('arrow')}</button>`;
  }else if(step===1){
    body=`<span class="eyebrow">ВОПРОС 1 ИЗ 4</span><h2>Как прошло<br>ваше посещение?</h2><p>Оцените общие впечатления от магазина.</p><div class="stars" role="group" aria-label="Оценка от 1 до 5">${[1,2,3,4,5].map(n=>`<button class="star ${k.rating>=n?'selected':''}" data-rating="${n}" aria-label="${n} из 5" aria-pressed="${k.rating===n}">★</button>`).join('')}</div><div class="kiosk-hint-row"><span>Не понравилось</span><span>Отлично</span></div>`;
    bottom=`<button class="secondary-btn" data-kiosk="back">Назад</button><button class="primary-btn" data-kiosk="next" ${!k.rating?'disabled':''}>Далее ${icon('arrow')}</button>`;
  }else if(step===2){
    body=`<span class="eyebrow">ВОПРОС 2 ИЗ 4</span><h2>Удалось купить<br>то, что искали?</h2><p>Мы не знаем, совершили ли вы покупку, пока вы сами не ответите.</p><div class="kiosk-options"><button class="kiosk-option ${k.purchased===true?'selected':''}" data-purchased="yes" aria-pressed="${k.purchased===true}">${icon('bag',27)} Да, купил(а)</button><button class="kiosk-option ${k.purchased===false?'selected':''}" data-purchased="no" aria-pressed="${k.purchased===false}">${icon('cross',27)} Нет, не купил(а)</button></div>${k.purchased===false?`<label class="kiosk-label">Почему не получилось?</label><div class="kiosk-reasons">${Object.entries(reasonLabels).map(([key,label])=>`<button type="button" class="kiosk-reason ${k.reason===key?'selected':''}" data-reason="${key}" aria-pressed="${k.reason===key}">${k.reason===key?icon('check',17):icon('chevron',17)} ${esc(label)}</button>`).join('')}</div>`:''}`;
    bottom=`<button class="secondary-btn" data-kiosk="back">Назад</button><button class="primary-btn" data-kiosk="next" ${k.purchased===null||(k.purchased===false&&!k.reason)?'disabled':''}>Далее ${icon('arrow')}</button>`;
  }else if(step===3){
    body=`<span class="eyebrow">ВОПРОС 3 ИЗ 4</span><h2>Что вам<br>понравилось?</h2><p>Выберите несколько вариантов или пропустите вопрос.</p>${tagButtons(likedOptions,'liked_tags',k.liked_tags)}<p class="kiosk-secondary-hint">Можно выбрать несколько ответов</p>`;
    bottom=`<button class="secondary-btn" data-kiosk="back">Назад</button><button class="primary-btn" data-kiosk="next">Далее ${icon('arrow')}</button>`;
  }else if(step===4){
    body=`<span class="eyebrow">ВОПРОС 4 ИЗ 4</span><h2>Что стоит<br><span class="red">улучшить?</span></h2><p>Ваши предложения действительно помогут — можно выбрать варианты и добавить комментарий.</p>${tagButtons(improveOptions,'improve_tags',k.improve_tags)}<form id="kiosk-form" class="kiosk-form"><label class="kiosk-label" for="liked">Что понравилось ещё? (необязательно)</label><input id="liked" name="liked" class="input kiosk-input" value="${esc(k.liked)}" maxlength="100" placeholder="Например, качество одежды"/><label class="kiosk-label" for="suggestion">Что бы вы добавили или изменили?</label><textarea id="suggestion" name="suggestion" class="textarea kiosk-input" rows="3" maxlength="400" placeholder="Например, больше курток размера XL">${esc(k.suggestion)}</textarea><div class="kiosk-buttons" style="margin-top:20px"><button type="button" class="secondary-btn" data-kiosk="back">Назад</button><button type="submit" class="primary-btn" id="kiosk-submit">Отправить ${icon('send')}</button></div></form>`;
  }else{
    body=`<div class="kiosk-thanks"><div class="thank-icon">${icon('check',45)}</div><span class="eyebrow">ОТВЕТ СОХРАНЁН</span><h2>Спасибо!</h2><p>Вы помогли сделать магазин лучше. Ваш отзыв учтён.</p>${state.kioskReward?`<div class="kiosk-incentive reward-display">${icon('gift',23)}<strong>${esc(state.kioskReward.label)}</strong><div class="reward-code">${esc(state.kioskReward.code)}</div><small>Покажите код сотруднику. Он проверяет бонус вручную, срок действия — 7 дней. Условия уточните в магазине.</small></div>`:st.incentive?`<div class="kiosk-incentive">${esc(st.incentive)}</div>`:''}</div>`;
    bottom=`<button class="primary-btn" data-kiosk="restart">Новый опрос ${icon('arrow')}</button>`;
  }
  const progress=step===0?0:step>=5?100:step*25;
  root.innerHTML=`<div class="kiosk-shell"><section class="kiosk-visual"><div class="kiosk-brand"><div class="brand">OSMAN<span>X</span></div><div class="brand-sub">RETAIL INTELLIGENCE</div></div><div class="kiosk-orb"></div><div class="kiosk-visual-body"><div class="eyebrow">ПРЕМИАЛЬНЫЙ СЕРВИС НАЧИНАЕТСЯ С ВАШЕГО МНЕНИЯ</div><h1>Ваш опыт.<br><span class="red">Наши решения.</span></h1><p>Каждое мнение помогает сделать следующий визит удобнее. Мы не просим личные данные.</p></div><div class="kiosk-visual-foot"><span>ПРОСТО</span><span>БЫСТРО</span><span>ДОБРОВОЛЬНО</span></div></section><main class="kiosk-right"><div class="kiosk-card"><header class="kiosk-card-top"><div><div class="brand" style="font-size:24px">OSMAN<span>X</span></div><div class="brand-sub" style="font-size:8px">RETAIL INTELLIGENCE</div></div><span class="kiosk-store">${esc(st.name)}</span></header><div class="progress" aria-label="Прогресс опроса"><div style="width:${progress}%"></div></div><div class="kiosk-card-body ${step===5?'is-complete':''}">${body}</div>${step!==4?`<footer class="kiosk-buttons">${bottom}</footer>`:''}<p class="kiosk-privacy">Опрос добровольный: без имени и распознавания лиц. Не указывайте контакты в комментарии. Ответы хранятся до ${Number(st.survey_retention_days||90)} дней. Бонус — при наличии и по правилам магазина.</p></div></main></div>`;
}
function openDialog(type){const dialog=document.getElementById('entry-dialog');if(!dialog)return;
 let title='',body='';
 if(type==='team'){
 title='Добавить сотрудника';body=`<form id="team-form" class="dialog-body"><div class="field"><label>Имя</label><input class="input" name="name" required minlength="2" maxlength="100" /></div><div class="field"><label>E-mail</label><input type="email" name="email" class="input" required /></div><div class="field"><label>Временный пароль (12+ символов)</label><input type="password" name="password" class="input" minlength="12" required autocomplete="new-password" /></div><div class="field"><label>Роль</label><select class="select" name="role"><option value="manager">Управляющий</option><option value="analyst">Аналитик</option><option value="viewer">Наблюдатель</option></select></div><div class="field"><label>Доступ к филиалу</label><select class="select" name="store">${state.stores.map(x=>`<option value="${esc(x.slug)}">${esc(x.name)}</option>`).join('')}</select></div><button type="submit" class="primary-btn">Создать аккаунт</button></form>`;
 }else if(type==='device'){
 title='Подключить датчик';body=`<form id="device-form" class="dialog-body"><p class="dialog-note">Создайте отдельную учётную запись для физического счётчика. Это только серверная регистрация: инженер должен настроить устройство на отправку подписанных событий.</p><div class="field"><label>Название</label><input class="input" name="name" minlength="2" maxlength="100" required placeholder="Счётчик у входа"/></div><div class="field"><label>Тип</label><select class="select" name="kind"><option value="traffic">Счётчик входов</option><option value="zones">События зон</option></select></div><button class="primary-btn" type="submit">Выдать отдельный ключ</button></form>`;
 }else if(type==='demand'){
 title='Новый запрос покупателя';body=`<form id="demand-form" class="dialog-body"><p class="dialog-note">Сохраняйте фактические обращения, даже если покупка не состоялась.</p><div class="field"><label>Название товара</label><input class="input" name="product" required minlength="2" maxlength="120" placeholder="Куртка демисезонная" autofocus/></div><div class="field-row"><div class="field"><label>Размер</label><input class="input" name="size" maxlength="30" placeholder="XL"/></div><div class="field"><label>Цвет</label><input class="input" name="color" maxlength="50" placeholder="Чёрный"/></div></div><button type="submit" class="primary-btn">${icon('check')} Сохранить запрос</button></form>`;
 }else if(type==='zone'){
 title='Новая зона магазина';body=`<form id="zone-form" class="dialog-body"><p class="dialog-note">Задайте название и положение зоны на условной схеме (0–100%). Затем подключите датчик, который отправляет только число событий.</p><div class="field"><label>Код зоны (латиница)</label><input class="input" name="code" required pattern="[a-z0-9][a-z0-9-]+" placeholder="vip-zone"/></div><div class="field"><label>Название</label><input class="input" name="name" required maxlength="70" placeholder="Примерочные"/></div><div class="field-row"><div class="field"><label>Положение X, %</label><input type="number" class="input" name="x" min="0" max="100" value="50" required/></div><div class="field"><label>Положение Y, %</label><input type="number" class="input" name="y" min="0" max="100" value="50" required/></div></div><button type="submit" class="primary-btn">${icon('check')} Сохранить зону</button></form>`;
 }else if(type==='stock'){
 title='Товар на складе';body=`<form id="stock-form" class="dialog-body"><p class="dialog-note">Артикул уникален в пределах филиала; повторная отправка обновит запись.</p><div class="field"><label>Артикул / SKU</label><input class="input" name="sku" maxlength="80" required placeholder="COAT-XL-BLK"/></div><div class="field"><label>Название товара</label><input class="input" name="product" maxlength="120" required placeholder="Куртка демисезонная"/></div><div class="field-row"><div class="field"><label>Размер</label><input class="input" name="size" maxlength="30" placeholder="XL"/></div><div class="field"><label>Цвет</label><input class="input" name="color" maxlength="50" placeholder="Чёрный"/></div></div><div class="field"><label>Остаток, шт.</label><input type="number" class="input" name="quantity" min="0" max="1000000" value="1" required/></div><button class="primary-btn" type="submit">${icon('check')} Сохранить</button></form>`;
 }else if(type==='stock-batch'){
 title='Импорт остатков';body=`<form id="stock-batch-form" class="dialog-body"><p class="dialog-note">Вставьте JSON-массив товаров. Никакого прямого подключения к 1С это не создаёт.</p><div class="field"><label>Товары в формате JSON</label><textarea class="textarea" name="records" rows="7" required spellcheck="false" placeholder='[{"sku":"JACKET-XL","product":"Куртка","size":"XL","color":"чёрный","quantity":4}]'></textarea></div><button class="primary-btn" type="submit">${icon('download')} Импортировать</button></form>`;
 }else if(type==='experiment'){
 title='Новая проверяемая гипотеза';body=`<form id="experiment-form" class="dialog-body"><div class="field"><label>Название эксперимента</label><input class="input" name="title" maxlength="120" minlength="4" required placeholder="Выдача отсутствующих размеров"/></div><div class="field"><label>Что мы предполагаем?</label><textarea class="textarea" name="hypothesis" maxlength="500" minlength="8" rows="3" required placeholder="Если подбирать размер в другом филиале, подтверждённых продаж станет больше"></textarea></div><div class="field"><label>Метрика успеха</label><select name="metric" class="select"><option value="confirmed_sales">Подтверждённые продажи</option><option value="conversion">Конверсия</option><option value="avg_receipt">Средний чек</option><option value="repeat_visits">Повторные визиты (при наличии данных)</option><option value="gross_profit">Валовая прибыль (при наличии данных)</option></select></div><div class="field"><label>Базовый показатель (необязательно)</label><input name="baseline" class="input" type="number" min="0" step="any" placeholder="Например, 20"/></div><button class="primary-btn" type="submit">${icon('check')} Создать план</button></form>`;
 }else if(type==='new-store'){
 title='Добавить филиал';body=`<form id="new-store-form" class="dialog-body"><p class="dialog-note">Данные филиалов изолируются по идентификатору магазина внутри общего кабинета владельца.</p><div class="field"><label>Название</label><input name="name" class="input" required minlength="2" maxlength="100" placeholder="Бутик на проспекте"/></div><div class="field"><label>Короткий код для ссылки (латиница)</label><input name="slug" class="input" required minlength="2" maxlength="41" pattern="[a-z0-9][a-z0-9-]+" placeholder="prospekt"/></div><button class="primary-btn" type="submit">${icon('plus')} Создать филиал</button></form>`;
 }else{
 const isSale=type==='sale';title=isSale?'Зарегистрировать покупку':'Новое событие посетителя';body=`<form id="event-form" class="dialog-body"><p class="dialog-note">Данные вручную добавятся к показателям магазина. Избегайте двойного учёта при подключённом датчике или кассе.</p><div class="field"><label>Тип события</label><select class="select" name="kind" id="event-kind"><option value="entry" ${isSale?'':'selected'}>Посетитель вошёл</option><option value="sale" ${isSale?'selected':''}>Покупка / чек</option><option value="interest">Интерес к товару</option><option value="fitting">Примерка</option></select></div><div class="field"><label>Количество (для покупок — 1 чек)</label><input class="input" type="number" name="quantity" min="1" max="500" value="1" required/></div><div class="field"><label>Сумма чека, ₽ (для продаж)</label><input class="input" type="number" name="amount_rub" min="0" max="20000000" step="0.01" value="0" /></div><button type="submit" class="primary-btn">${icon('check')} Добавить событие</button></form>`;
 }
 dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="dialog-x" type="button" data-action="close-dialog" aria-label="Закрыть">×</button></div>${body}`;dialog.showModal();
}
async function showMatches(id){try{const result=await api(`/admin/demand/${id}/matches`,{auth:true});const dialog=document.querySelector('#entry-dialog');if(!dialog)return;dialog.innerHTML=`<div class="dialog-head"><h2>Поиск по филиалам</h2><button class="dialog-x" type="button" data-action="close-dialog">×</button></div><div class="dialog-body">${result.matches.length?result.matches.map(m=>`<div class="quality-line"><span><b>${esc(m.store_name)}</b><small style="display:block">${esc(m.product)} · ${esc(m.size)} · ${esc(m.color)}</small></span><strong>${integer(m.quantity)} шт.</strong></div>`).join(''):'<p class="tip">Совпадающих товаров с положительным остатком пока нет.</p>'}<div class="note separated">${esc(result.method)}</div></div>`;dialog.showModal()}catch(e){toast(e.message,true)}}
function confirmDemandDialog(id){const dialog=document.querySelector('#entry-dialog');if(!dialog)return;dialog.innerHTML=`<div class="dialog-head"><h2>Подтвердить завершённую покупку</h2><button type="button" class="dialog-x" data-action="close-dialog">×</button></div><form id="confirm-demand-form" class="dialog-body"><input type="hidden" name="demand_id" value="${id}"/><p class="dialog-note">Система зачтёт результат только с чеком этого магазина, оформленным после запроса покупателя. Один чек нельзя дважды привязать к разным запросам.</p><div class="field"><label>Внутренний ID чека в OSMANX</label><input name="sale_id" type="number" class="input" min="1" required placeholder="Например, 123" /></div><button type="submit" class="primary-btn">${icon('check')} Привязать чек</button></form>`;dialog.showModal()}
function editExperiment(id){const e=state.experiments.find(x=>x.id===id);if(!e)return;const dialog=document.querySelector('#entry-dialog');if(!dialog)return;dialog.innerHTML=`<div class="dialog-head"><h2>Результат эксперимента</h2><button class="dialog-x" type="button" data-action="close-dialog">×</button></div><form id="experiment-update-form" class="dialog-body"><input name="id" type="hidden" value="${e.id}"/><strong>${esc(e.title)}</strong><p class="dialog-note">Не завершайте пилот без измеренного результата. При сравнении учтите сезонность и внешние факторы.</p><div class="field"><label>Статус</label><select name="status" class="select">${Object.entries({planned:'Планируется',running:'В работе',finished:'Завершён',cancelled:'Отменён'}).map(([k,v])=>`<option value="${k}" ${e.status===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Фактически измеренная метрика</label><input class="input" name="result" type="number" min="0" step="any" value="${e.result??''}" placeholder="Например, 21.5"/></div><div class="field"><label>Что делали и что выяснили</label><textarea name="notes" class="textarea" maxlength="1000" rows="4">${esc(e.notes||'')}</textarea></div><button class="primary-btn" type="submit">${icon('check')} Сохранить</button></form>`;dialog.showModal()}
function updateScenario(){const pp=Number(document.getElementById('scenario-pp')?.value||2),margin=Number(document.getElementById('scenario-margin')?.value||45);const label=document.getElementById('scenario-pp-label');const revenue=document.getElementById('scenario-revenue');const profit=document.getElementById('scenario-profit');if(!label||!revenue||!profit)return;label.textContent=`${pp.toString().replace('.',',')} п.п.`;const d=state.data;const potential=d.visitors*pp/100*d.avg_receipt;revenue.textContent=money(potential);profit.textContent=money(potential*Math.min(100,Math.max(0,margin))/100)}
async function handleClick(event){
 const button=event.target.closest('button,[data-action],[data-nav],[data-dialog],[data-days],[data-rating],[data-kiosk]');if(!button)return;
 if(button.matches('button')&&button.disabled)return;
 if(button.dataset.nav){state.page=button.dataset.nav;state.menuOpen=false;render();if(state.page==='actions')updateScenario();scrollTo({top:0,behavior:'smooth'});return}
 if(button.dataset.days){state.days=Number(button.dataset.days);await refresh();return}
 if(button.dataset.dialog){openDialog(button.dataset.dialog);return}
 if(button.dataset.matches){await showMatches(Number(button.dataset.matches));return}
 if(button.dataset.confirmDemand){confirmDemandDialog(Number(button.dataset.confirmDemand));return}
 if(button.dataset.experimentId){editExperiment(Number(button.dataset.experimentId));return}
 if(button.dataset.export){try{await downloadReport(`/admin/export/${button.dataset.export}.csv?slug=${encodeURIComponent(state.slug)}`,`osmanx-${button.dataset.export}-${state.slug}.csv`);toast('Отчёт скачан')}catch(e){toast(e.message,true)}return}
 if(button.dataset.kioskTag){const kind=button.dataset.kioskTagKind,key=button.dataset.kioskTag;const tags=state.kiosk[kind];if(kind==='improve_tags'){state.kiosk.liked=document.querySelector('#liked')?.value||state.kiosk.liked;state.kiosk.suggestion=document.querySelector('#suggestion')?.value||state.kiosk.suggestion}state.kiosk[kind]=tags.includes(key)?tags.filter(x=>x!==key):[...tags,key];renderKiosk();return}
 if(button.dataset.rating){state.kiosk.rating=Number(button.dataset.rating);renderKiosk();return}
 if(button.dataset.purchased){state.kiosk.purchased=button.dataset.purchased==='yes';state.kiosk.reason='';renderKiosk();return}
 if(button.dataset.reason){state.kiosk.reason=button.dataset.reason;renderKiosk();return}
 if(button.dataset.kiosk){const action=button.dataset.kiosk;
    if(action==='restart'){state.kiosk=freshKiosk();state.kioskReward=null;state.kioskStep=0}
    else if(action==='start')state.kioskStep=1;
    else if(action==='back')state.kioskStep=Math.max(0,state.kioskStep-1);
    else if(action==='next'){
      if(state.kioskStep===1&&!state.kiosk.rating)return;
      if(state.kioskStep===2&&(state.kiosk.purchased===null||(state.kiosk.purchased===false&&!state.kiosk.reason)))return;
      state.kioskStep=Math.min(4,state.kioskStep+1);
    }
    renderKiosk();return;
 }
 if(button.dataset.quick){try{await api('/admin/events',{method:'POST',auth:true,body:{slug:state.slug,kind:button.dataset.quick,quantity:1,amount_rub:0}});toast('Событие записано');await refresh()}catch(e){toast(e.message,true)}return}
 if(button.dataset.teamToggle){const id=Number(button.dataset.teamToggle);const item=state.team.find(x=>x.id===id);if(!item)return;
    if(!confirm(`${item.active?'Отключить':'Активировать'} доступ ${item.email}?`))return;
    try{await api(`/admin/team/${id}`,{method:'PATCH',auth:true,body:{active:!item.active,stores:item.stores}});state.team=await api('/admin/team',{auth:true});render();toast('Доступ изменён, предыдущие сессии отозваны')}catch(e){toast(e.message,true)}return}
 if(button.dataset.deviceRotate){if(!confirm('Старый секрет устройства перестанет работать. Продолжить?'))return;
    try{const x=await api(`/admin/devices/${encodeURIComponent(button.dataset.deviceRotate)}/rotate`,{method:'POST',auth:true});const dlg=document.querySelector('#entry-dialog');dlg.innerHTML=`<div class="dialog-head"><h2>Новый ключ</h2><button class="dialog-x" data-action="close-dialog">×</button></div><div class="dialog-body"><p class="quality-warning">Сохраните новый секрет сейчас.</p><pre class="code">Устройство: ${esc(x.device_id)}
Секрет: ${esc(x.secret)}</pre></div>`;dlg.showModal();toast('Ключ обновлён')}catch(e){toast(e.message,true)}return}
 if(button.dataset.deviceRevoke){if(!confirm('Отключить устройство и запретить новые события?'))return;
    try{await api(`/admin/devices/${encodeURIComponent(button.dataset.deviceRevoke)}`,{method:'DELETE',auth:true});await refresh();toast('Устройство отключено')}catch(e){toast(e.message,true)}return}
 if(button.dataset.posRotate){if(!confirm('Перевыпустить ключ кассы? Старый перестанет работать.'))return;try{const x=await api(`/admin/pos/sources/${encodeURIComponent(button.dataset.posRotate)}/rotate`,{method:'POST',auth:true});await refresh();const dlg=document.querySelector('#entry-dialog');dlg.innerHTML=`<div class="dialog-head"><h2>Новый ключ кассы</h2><button data-action="close-dialog">×</button></div><div class="dialog-body"><p class="quality-warning">Сохраните секрет сейчас.</p><pre class="code">${esc(x.source_id)}
${esc(x.secret)}</pre></div>`;dlg.showModal()}catch(e){toast(e.message,true)}return}
 if(button.dataset.posRevoke){if(!confirm('Отключить источник чеков?'))return;try{await api(`/admin/pos/sources/${encodeURIComponent(button.dataset.posRevoke)}`,{method:'DELETE',auth:true});await refresh();toast('Источник отключён')}catch(e){toast(e.message,true)}return}
 switch(button.dataset.action){
  case 'import-apply':{
    if(!state.pendingImport)return;
    if(!confirm('Применить проверенный импорт к этому филиалу?'))return;
    try{const result=await api('/admin/imports/apply',{method:'POST',auth:true,body:{batch_key:state.pendingImport.batch_key}});state.pendingImport=null;await refresh();toast(`Импорт применён: ${result.summary.added} новых записей`)}catch(e){toast(e.message,true)}return;
  }
  case 'retry':await init();break;
  case 'menu':state.menuOpen=!state.menuOpen;render();break;
  case 'open-kiosk':window.open(`/kiosk/${encodeURIComponent(state.slug)}`,'_blank','noopener');break;
  case 'copy-kiosk':try{if(state.store?.kiosk_required&&!state.kioskLink)throw new Error('Сначала создайте ссылку привязки в настройках');await navigator.clipboard.writeText(state.kioskLink||location.origin+'/kiosk/'+state.slug);toast('Ссылка скопирована')}catch{toast('Не удалось скопировать автоматически',true)}break;
  case 'close-dialog':document.querySelector('#entry-dialog')?.close();break;
  case 'refresh-monitor':await refresh();toast('Данные обновлены');break;
  case 'pair-kiosk':{
    if(!confirm('Создать новый секрет? Предыдущие привязанные планшеты перестанут отправлять ответы.'))break;
    try{const pair=await api(`/admin/kiosks/${encodeURIComponent(state.slug)}/rotate`,{method:'POST',auth:true});
      state.kioskLink=location.origin+`/kiosk/${state.slug}`+pair.pair_url_fragment;
      state.stores=[];await refresh();
      const dlg=document.querySelector('#entry-dialog');if(dlg){dlg.innerHTML=`<div class="dialog-head"><h2>Терминал привязан</h2><button class="dialog-x" data-action="close-dialog">×</button></div><div class="dialog-body"><p class="quality-warning">Сохраните ссылку сейчас: секрет повторно не отображается.</p><textarea class="textarea" readonly rows="5">${esc(state.kioskLink)}</textarea><button class="secondary-btn" data-action="copy-paired-kiosk">Скопировать ссылку</button></div>`;dlg.showModal()}
    }catch(e){toast(e.message,true)}break;
  }
  case 'copy-paired-kiosk':try{await navigator.clipboard.writeText(state.kioskLink||'');toast('Защищённая ссылка скопирована')}catch{toast('Не удалось скопировать',true)}break;
  case 'unpair-kiosk':{
    if(!confirm('Отключить защиту: опросник снова будет принимать публичные ответы?'))break;
    try{await api(`/admin/kiosks/${encodeURIComponent(state.slug)}`,{method:'DELETE',auth:true});state.kioskLink=null;state.stores=[];await refresh();toast('Привязка отключена')}
    catch(e){toast(e.message,true)}break;
  }
  case 'logout-all':try{await api('/auth/logout-all',{method:'POST',auth:true});setToken('');state.data=null;state.user=null;state.stores=[];renderLogin();toast('Все сессии завершены')}catch(e){toast(e.message,true)}break;
  case 'logout':setToken('');state.data=null;state.user=null;state.stores=[];state.devices=[];state.team=[];renderLogin();break;
 }
}
async function handleSubmit(event){const form=event.target;if(!form?.id)return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
 try{
  const data=Object.fromEntries(new FormData(form));
  if(form.id==='kiosk-access-form'){
    const token=String(data.token||'').trim();if(!/^[a-zA-Z0-9_-]{30,160}$/.test(token))throw new Error('Неверный формат ключа');
    sessionStorage.setItem(`osmanx_kiosk_${state.slug}`,token);state.kioskToken=token;renderKiosk();return;
  }
  if(form.id==='change-password-form'){
    const response=await api('/auth/change-password',{method:'POST',auth:true,body:{current_password:data.current_password,new_password:data.new_password}});
    setToken(response.token);form.reset();toast('Пароль изменён, предыдущие сессии отозваны');return;
  }
  if(form.id==='pos-source-form'){
    const result=await api('/admin/pos/sources',{method:'POST',auth:true,body:{slug:state.slug,name:data.name}});
    await refresh();const dlg=document.querySelector('#entry-dialog');if(dlg){dlg.innerHTML=`<div class="dialog-head"><h2>Новый источник чеков</h2><button class="dialog-x" data-action="close-dialog">×</button></div><div class="dialog-body"><p class="quality-warning">Сохраните секрет сейчас: повторно его получить нельзя.</p><pre class="code">ID: ${esc(result.source_id)}
Секрет: ${esc(result.secret)}</pre></div>`;dlg.showModal()}return;
  }
  if(form.id==='import-preview-form'){
    let records;try{records=JSON.parse(data.records)}catch{throw new Error('Неверный JSON')}
    if(!Array.isArray(records))throw new Error('Передайте массив записей');
    state.pendingImport=await api('/admin/imports/preview',{method:'POST',auth:true,body:{slug:state.slug,kind:data.kind,rows:records}});
    state.page='integrations';render();toast('Предпросмотр готов. Данные магазина не изменены.');return;
  }
  if(form.id==='device-form'){
    const result=await api('/admin/devices',{method:'POST',auth:true,body:{slug:state.slug,name:data.name,kind:data.kind}});
    const dlg=document.querySelector('#entry-dialog');
    if(dlg)dlg.innerHTML=`<div class="dialog-head"><h2>Ключ устройства создан</h2><button class="dialog-x" data-action="close-dialog">×</button></div><div class="dialog-body"><p class="quality-warning">Сохраните секрет сейчас: он больше не будет показан.</p><pre class="code">Устройство: ${esc(result.device_id)}
Секрет: ${esc(result.secret)}</pre></div>`;
    state.devices=await api(`/admin/devices?slug=${encodeURIComponent(state.slug)}`,{auth:true});toast('Устройство зарегистрировано');return;
  }
  if(form.id==='team-form'){
    const result=await api('/admin/team',{method:'POST',auth:true,body:{email:data.email,name:data.name,password:data.password,role:data.role,stores:[data.store]}});
    document.querySelector('#entry-dialog')?.close();state.team=await api('/admin/team',{auth:true});toast('Сотрудник создан');render();return;
  }
  if(form.id==='login-form'){
    const result=await api('/auth/login',{method:'POST',body:{email:data.email||null,password:data.password}});
    setToken(result.token);state.error='';state.user=null;state.stores=[];await refresh();toast('Вход выполнен');return;
  }
  if(form.id==='kiosk-form'){
    state.kiosk.liked=String(data.liked||'').trim();state.kiosk.suggestion=String(data.suggestion||'').trim();
    let submitted;try{submitted=await api(`/public/survey/${encodeURIComponent(state.slug)}`,{method:'POST',body:{...state.kiosk},kioskToken:state.kioskToken});}
    catch(error){if(state.store?.kiosk_required&&/token|401|доступ|access/i.test(error.message)){sessionStorage.removeItem(`osmanx_kiosk_${state.slug}`);state.kioskToken=null;renderKiosk()}throw error}
    state.kioskReward=submitted.reward||null;
    state.kioskStep=5;renderKiosk();return;
  }
  if(form.id==='demand-form'){
    await api('/admin/demand',{method:'POST',auth:true,body:{slug:state.slug,product:data.product,size:data.size,color:data.color}});
    document.querySelector('#entry-dialog')?.close();toast('Запрос сохранён');await refresh();return;
  }
  if(form.id==='event-form'){
    await api('/admin/events',{method:'POST',auth:true,body:{slug:state.slug,kind:data.kind,quantity:Number(data.quantity),amount_rub:Number(data.amount_rub)}});
    document.querySelector('#entry-dialog')?.close();toast('Событие добавлено');await refresh();return;
  }
  if(form.id==='zone-form'){
    await api('/admin/zones',{method:'POST',auth:true,body:{slug:state.slug,code:data.code,name:data.name,x:Number(data.x),y:Number(data.y)}});
    document.querySelector('#entry-dialog')?.close();toast('Зона сохранена');await refresh();return;
  }
  if(form.id==='stock-form'||form.id==='stock-batch-form'){
    let records;
    if(form.id==='stock-form')records=[{sku:data.sku,product:data.product,size:data.size,color:data.color,quantity:Number(data.quantity)}];
    else{try{records=JSON.parse(data.records)}catch{throw new Error('Неверный JSON')};if(!Array.isArray(records))throw new Error('Ожидается массив товаров')}
    const result=await api('/admin/stock/import',{method:'POST',auth:true,body:{slug:state.slug,items:records,source:form.id==='stock-form'?'manual':'csv_import'}});
    document.querySelector('#entry-dialog')?.close();toast(`Сохранено: ${result.imported} позиций`);await refresh();return;
  }
  if(form.id==='experiment-form'){
    await api('/admin/experiments',{method:'POST',auth:true,body:{slug:state.slug,title:data.title,hypothesis:data.hypothesis,metric:data.metric,baseline:data.baseline?Number(data.baseline):null}});
    document.querySelector('#entry-dialog')?.close();toast('Пилот создан');await refresh();return;
  }
  if(form.id==='experiment-update-form'){
    await api(`/admin/experiments/${data.id}`,{method:'PATCH',auth:true,body:{status:data.status,result:data.result===''?null:Number(data.result),notes:data.notes||''}});
    document.querySelector('#entry-dialog')?.close();toast('Результат сохранён');await refresh();return;
  }
  if(form.id==='new-store-form'){
    await api('/admin/stores',{method:'POST',auth:true,body:{name:data.name,slug:data.slug,timezone:'Europe/Moscow'}});
    document.querySelector('#entry-dialog')?.close();state.stores=[];state.slug=data.slug;toast('Филиал создан');await refresh();return;
  }
  if(form.id==='confirm-demand-form'){
    await api(`/admin/demand/${data.demand_id}/convert`,{method:'POST',auth:true,body:{sale_id:Number(data.sale_id)}});
    document.querySelector('#entry-dialog')?.close();toast('Покупка подтверждена чеком');await refresh();return;
  }
  if(form.id==='redeem-form'){
    await api('/admin/rewards/redeem',{method:'POST',auth:true,body:{slug:state.slug,code:data.code}});
    toast('Код погашен. Проверьте условия акции перед выдачей бонуса.');form.reset();return;
  }
  if(form.id==='store-form'){
    await api(`/admin/store/${encodeURIComponent(state.slug)}`,{method:'PUT',auth:true,body:{name:data.name,subtitle:data.subtitle,incentive:data.incentive,timezone:data.timezone,reward_enabled:form.elements.reward_enabled.checked,reward_label:data.reward_label,reward_daily_limit:Number(data.reward_daily_limit),survey_retention_days:Number(data.survey_retention_days),traffic_mode:data.traffic_mode}});
    state.stores=[];toast('Настройки сохранены');await refresh();return;
  }
  if(form.id==='import-form'){
    let records;try{records=JSON.parse(data.records)}catch{throw new Error('Неверный формат JSON')}
    if(!Array.isArray(records))throw new Error('Ожидается массив чеков');
    const result=await api('/admin/import/pos',{method:'POST',auth:true,body:{slug:state.slug,sales:records}});
    toast(`Импортировано ${result.imported}, пропущено повторов ${result.duplicates}`);await refresh();return;
  }
 }catch(e){toast(e.message||'Ошибка операции',true)}finally{if(submit&&submit.isConnected)submit.disabled=false}
}
async function handleChange(event){const target=event.target;if(target.id==='select-store'){state.slug=target.value;await refresh()}
 if(target.dataset.demandId){try{await api(`/admin/demand/${target.dataset.demandId}`,{method:'PATCH',auth:true,body:{status:target.value}});toast('Статус обновлён');await refresh()}catch(e){toast(e.message,true);await refresh()}}
 if(target.id==='scenario-pp'||target.id==='scenario-margin')updateScenario();
}
document.addEventListener('click',handleClick);
document.addEventListener('submit',handleSubmit);
document.addEventListener('change',handleChange);
